function summary=validate_hcp_stage3_pcm(workspace)
%VALIDATE_HCP_STAGE3_PCM 两被试旧TYPEB beta；显式工程噪声，不冒充白化科研输入。
if nargin<1,workspace=fileparts(fileparts(fileparts(mfilename('fullpath'))));end
addpath(fullfile(workspace,'function_toolkit'));setup_function('D:/matlab/atoolbox/spm12');out=fullfile(workspace,'derivatives','function_stage3_pcm_20261017');if isfolder(out),error('cog:Exists','Preserve successful output');end;mkdir(out);
catalog=fullfile(workspace,'derivatives','function_stage1_real_20261016','patterns_results','selected_catalog.tsv');t=cog.read_tsv(catalog);subjects=unique(t.subject,'stable');manifest=table;
for k=1:numel(subjects)
    sub=t(t.subject==subjects(k),:);file=fullfile(out,subjects(k)+"_betas.tsv");writetable(sub,file,'FileType','text','Delimiter','\t');[x,meta,space]=cog.load_betas(file,2);pick=round(linspace(1,size(x,2),64));
    data=struct('y',x(:,pick),'condition',meta.condition,'partition',meta.session+"/"+meta.run,'rowNoiseCovariance',eye(size(x,1)),'noiseNote','Engineering identity observation covariance and unwhitened sampled features; GLMsingle shared HRF across runs. No scientific row/feature independence or crossvalidation claim.','spatialNoiseState','unwhitened_engineering','featureIds',string(space.indices(pick)),'sourceCatalog',file);input=fullfile(out,subjects(k)+"_data.mat");save(input,'data');manifest=[manifest;table(subjects(k),string(input),'VariableNames',{'subject','data_file'})]; %#ok<AGROW>
end
file=fullfile(out,'subjects.tsv');writetable(manifest,file,'FileType','text','Delimiter','\t');c=pcm_config;c.manifestFile=file;c.pcmPath='D:/matlab/atoolbox/pcm_toolbox-master/pcm_toolbox-master';c.conditionLabels={'story','math'};v=[1;-1];c.models={struct('name','null','type','fixed','Gc',zeros(2)),struct('name','contrast','type','fixed','Gc',v*v')};c.options.allowEngineeringNoise=true;c.options.maxIterations=40;c.execute=true;
for mode={'individual','group'},c.options.mode=mode{1};c.outputRoot=fullfile(out,mode{1});r=run_pcm(c);summary.(mode{1})=struct('status',r.status,'likelihood',r.likelihood);end
summary.skipped={'Real group CV: only two prepared independent subjects (<3 required).','Real individual CV: only two run partitions (<3 required for >=2 train partitions).','Multiple independent components after fixed run removal: two conditions provide only one centered contrast dimension.'};summary.scope='Two HCP subjects, 50 total TYPEB units, 64 fixed sampled features each, fixed null/contrast individual/group PCM. Explicit engineering identity/unwhitened-noise opt-in; no model plausibility/likelihood inference/white-noise or sufficient convergence claim. Crossvalidation/component functions independently synthetic tested.';cog.write_json(fullfile(out,'VALIDATION.json'),summary);
end
